const rec = (input.records || [])[0];
if (!rec) return { ...input, hasRequest: false };
const f = rec.fields || {};
const status = f.Status || "Pending";
return { ...input, hasRequest: true, recordId: rec.id, patientName: f.PatientName || "patient", contactEmail: f.Email || "", status, needsStaff: status === "Denied" || status === "More Info Needed" };
